// launcher.d.ts — the `launcher` bridge of the launcher core, for the scripts of a pack.
// Generated by `cargo xtask bridge-types` from the bridge's Rust types and the signatures in
// launcher-global/crates/launcher-pack/src/bridge.d.ts. Do not edit; regenerate.
//
// Reference it from the pack's scripts, for example with
// `/// <reference path="../launcher.d.ts" />` or the `types` of a jsconfig.json.

type Phase = "checking" | "downloading" | "verifying" | "blocked" | "ready" | "launching" | "launched" | "launch_failed";

type AntiCheatStatus = "checking" | "updating" | "ready" | "unavailable" | "error";

type AntiCheat = { status: AntiCheatStatus, simulated: boolean, };

type AntiCheatMessage = { title: string, message: string, dismissible: boolean, };

type BlockedProcess = { name: string, pid: number, };

type Download = { downloaded: number | null, total: number | null, speed: number | null, eta: number | null, };

type Snapshot = { phase: Phase, 
/**
 * 0 to 100.
 */
progress: number, installedVersion: number, clientVersion: number, 
/**
 * The check or the game sync failed: the phase stays `checking` until `repair` or `retry`.
 */
checkFailed: boolean, 
/**
 * While `blocked`: the processes that hold game files; empty in every other phase.
 */
blocked: Array<BlockedProcess>, 
/**
 * Download metrics while `downloading` or `blocked`.
 */
download: Download, anticheat: AntiCheat, 
/**
 * The last anti-cheat error, until `retry`.
 */
message: AntiCheatMessage | null, };

type RequestOp = "play" | "check" | "repair" | "forceClose" | "retry";

type ErrorCode = "invalidArgument" | "notAllowed" | "notFound" | "tooLarge" | "invalidJson" | "networkDenied" | "timeout" | "status" | "network" | "browserFailed" | "dialogFailed" | "quotaExceeded" | "readOnly";

/** An error the bridge throws or rejects with. */
interface LauncherError extends Error {
  code: ErrorCode;
  /** `fetchJson` with code `status`: the HTTP status. */
  status?: number;
}

interface LauncherWindow {
  /** Start moving the window. Effective only inside a primary `pointerdown` listener. */
  drag(): void;
  minimize(): void;
  /** Ask the core to close the window; it may refuse while a launch runs. */
  close(): void;
}

interface LauncherCache {
  /**
   * Store `value` under `key` for `options.ttl` seconds (1 to 2 592 000, 30 days). Throws a
   * `RangeError` with code `quotaExceeded` when the 8 MiB quota is full (nothing is evicted)
   * and a `TypeError` with code `invalidArgument` for a TTL out of range. Main window only.
   */
  put(key: string, value: string, options: { ttl: number }): void;
  /** The value under `key`, or `null` when absent or expired. */
  get(key: string): string | null;
  /** Remove `key`. Main window only. */
  delete(key: string): void;
}

interface Launcher {
  /**
   * The session's presentation, frozen; a new object at every revision. In the core's own
   * screens, the screen's state.
   */
  readonly snapshot: Snapshot;
  /** Call `listener` with every new snapshot. Returns the function that unsubscribes. */
  subscribe(listener: (snapshot: Snapshot) => void): () => void;
  /**
   * The page is ready: the window appears. An uncaught error or an unhandled rejection before
   * this call, or 10 s without it, fails the boot and the core shows its error screen.
   */
  ready(): void;
  /**
   * Main window: ask the session for `op`. The session revalidates it (phase, anti-cheat);
   * accepting the call does not mean it runs. Throws a `TypeError` with code `invalidArgument`
   * for an unknown op.
   */
  request(op: RequestOp): void;
  /**
   * Main window: open an HTTPS URL whose host is in `allowed_hosts` (or a subdomain of one) in
   * the browser. Rejects with code `notAllowed` or `browserFailed`.
   */
  openUrl(url: string): Promise<void>;
  /**
   * Main window: the Windows folder dialog, starting in `start` when it is an existing folder.
   * Resolves with the chosen path, or `null` on Cancel. Rejects with code `dialogFailed`, or
   * `tooLarge` for a path over 1024 characters.
   */
  pickFolder(start?: string): Promise<string | null>;
  /** Main window and core screens. */
  readonly window: LauncherWindow;
  /**
   * A JSON file of the pack, by pack-relative path (no `..`, drive, scheme, `\` or `%`), up to
   * 2 MiB. Rejects with code `invalidArgument`, `notFound`, `tooLarge` or `invalidJson`.
   */
  readJson<T = unknown>(path: string): Promise<T>;
  /**
   * Main window: GET an HTTPS URL of a host in `network_hosts` (or a subdomain of one), off the
   * UI thread: 10 s timeout, body up to 2 MiB, 4 requests at a time, no redirects. Resolves with
   * the parsed JSON body of a 2xx response. Rejects with code `notAllowed`, `networkDenied`,
   * `timeout`, `status`, `tooLarge`, `invalidJson` or `network`.
   */
  fetchJson<T = unknown>(url: string): Promise<T>;
  /** Strings with a TTL, in a file apart from `localStorage`. The splash may only `get`. */
  readonly cache: LauncherCache;
  /** Core screens only: a request to the core. Throws a `RangeError` over 64 KiB. */
  command(name: string, args?: unknown): void;
}

/**
 * The bridge. Present in every document; the members a document type does not offer are
 * absent (see each member). `localStorage` is the standard Web Storage, 5 MiB, kept in a file
 * per game: read-write in the main window, read-only in the splash (writes throw a `TypeError`
 * with code `readOnly`). `navigator.language` is the Windows UI language.
 */
declare const launcher: Launcher;
